def _число_рубильника_полосы(рез) -> str | None:
    """«итог / рубильник SOL» для тревоги. Нет числа -- None, и в строке черта.

    Берётся из состояния гейта, а не из текста причины: разбор своей же фразы
    -- это вторая версия правила, и она разойдётся с первой на первой правке.
    """
    с = (рез or {}).get("lane_state") or {}
    итог = с.get("pnl_chain_all_groups_sol")
    if итог is None:
        итог = с.get("pnl_chain_sol")
    if not isinstance(итог, (int, float)):
        return None
    try:
        import bloom_own_send as _OS  # noqa: PLC0415

        предел = _OS.СТОП_ПОЛОСЫ_СУТКИ_SOL
    except Exception:  # noqa: BLE001
        return f"{float(итог):+.3f} SOL"
    # СТОПА МОЖЕТ НЕ БЫТЬ ВОВСЕ (правило 16): тогда печатать "/ -None SOL" или
    # "/ -0 SOL" значило бы назвать предел, которого нет. Печатается только итог.
    if предел is None:
        return f"{float(итог):+.3f} SOL"
    return f"{float(итог):+.3f} / -{float(предел):g} SOL"
# Флаги -- не коды. Код один на решение, флагов может быть несколько, и
# они не меняют решения: покупка по минту при отсутствии пула остаётся
# покупкой, а расхождение маршрутов -- поводом для доклада, не для отказа.
КОД_РАЗБОР_УПАЛ = "HANDLER_CRASHED"
# Наша покупка ушла, но В ЦЕПИ УПАЛА (meta.err не null). Это не покупка:
# токена нет, позиции нет, ждать авто-ордер Bloom не от чего.
