САМОПРОВЕРКА_СВЕЖЕСТЬ_S = float(os.environ.get("BLOOM_SAMOPROVERKA_SVEZHEST_S") or 5400)
# ОКНО, ЗА КОТОРОЕ ДОКЛАД BUY ЕЩЁ ИМЕЕТ СМЫСЛ. Срок доклада считается от
